const STORE_SQL=`-- Store Notes: synchronize the 31-store master list\ncreate temporary table store_notes_import(store_code text,store_name text,area text,area_manager text,remarks text) on commit drop;\ninsert into store_notes_import values\n${valuesSql};\nupdate public.stores s set store_code=i.store_code,area=i.area,district=i.area,is_active=true from store_notes_import i where lower(s.store_name)=lower(i.store_name);\ninsert into public.stores(store_code,store_name,area,district,is_active) select i.store_code,i.store_name,i.area,i.area,true from store_notes_import i where not exists(select 1 from public.stores s where lower(s.store_name)=lower(i.store_name));\nupdate public.stores set is_active=false where store_code not in(select store_code from store_notes_import);\n`;
const WORKFLOW_SQL=`-- Store Notes role workflow security update
drop policy if exists findings_insert on public.findings;
create policy findings_insert on public.findings for insert to authenticated with check(created_by=auth.uid() and public.my_role()='regional_manager' and public.can_access_store(store_id));
drop policy if exists findings_delete on public.findings;
create policy findings_delete on public.findings for delete to authenticated using(public.my_role()='regional_manager');
drop policy if exists storage_delete on storage.objects;
create policy storage_delete on storage.objects for delete to authenticated using(bucket_id='store-findings' and public.my_role()='regional_manager');

create or replace function public.validate_area_manager_assignment() returns trigger language plpgsql security definer set search_path=public as $$begin
 if new.assigned_to is null or not exists(select 1 from profiles p join user_store_access a on a.user_id=p.id where p.id=new.assigned_to and p.role='area_manager' and p.is_active and a.store_id=new.store_id) then raise exception 'Finding must be assigned to the Area Manager responsible for the selected store'; end if;
 return new;
end$$;
drop trigger if exists finding_area_manager_assignment on public.findings;
create trigger finding_area_manager_assignment before insert or update of store_id,assigned_to on public.findings for each row execute function public.validate_area_manager_assignment();

create or replace function public.protect_finding_update() returns trigger language plpgsql security definer set search_path=public as $$
declare r app_role:=public.my_role();
begin
 if r in ('store_manager','area_manager') and (to_jsonb(new)-array['status','updated_at']) is distinct from (to_jsonb(old)-array['status','updated_at']) then raise exception 'Only workflow status may be changed for this role'; end if;
 if r='area_manager' and new.status<>old.status and not (old.status='OPEN' and new.status='IN_PROGRESS') then raise exception 'Area Manager may only acknowledge an open finding'; end if;
 if r='store_manager' and new.status<>old.status then
  if not (old.status='IN_PROGRESS' and new.status='FOR_VERIFICATION') then raise exception 'Store Manager may only submit acknowledged work for validation'; end if;
  if not exists(select 1 from finding_photos p where p.finding_id=old.id and p.photo_type='AFTER') then raise exception 'A confirmation photo is required before validation'; end if;
 end if;
 if new.status='CLOSED' and r<>'regional_manager' then raise exception 'Only Regional Manager may validate and mark Done'; end if;
 if new.is_archived and r<>'regional_manager' then raise exception 'Only Regional Manager may archive'; end if;
 return new;
end$$;

create or replace function public.log_photo_activity() returns trigger language plpgsql security definer set search_path=public as $$begin insert into finding_activity(finding_id,user_id,activity_type,description) values(new.finding_id,new.uploaded_by,'PHOTO_ADDED',case when new.photo_type='AFTER' then 'Confirmation photo uploaded' else initcap(lower(new.photo_type::text))||' photo uploaded' end);return new;end$$;
drop trigger if exists photo_activity on public.finding_photos;
create trigger photo_activity after insert on public.finding_photos for each row execute function public.log_photo_activity();
`;
const NOTIFICATION_SQL=`-- Enable authorized realtime notifications for new findings
do $$begin
 if not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename='findings') then alter publication supabase_realtime add table public.findings; end if;
end$$;
`;
const FULL_SQL=SQL+'\n'+STORE_SQL+'\n'+WORKFLOW_SQL+'\n'+NOTIFICATION_SQL;

function parseCsv(text){const lines=text.replace(/^\uFEFF/,'').split(/\r?\n/).filter(Boolean);const parse=line=>{const out=[];let v='',q=false;for(let i=0;i<line.length;i++){const c=line[i];if(c==='"'&&q&&line[i+1]==='"'){v+='"';i++}else if(c==='"')q=!q;else if(c===','&&!q){out.push(v);v=''}else v+=c}out.push(v);return out};const headers=parse(lines.shift());return lines.map(line=>Object.fromEntries(parse(line).map((v,i)=>[headers[i],v.trim()]))) }
async function provisionUsers(filePath){
 const url=process.env.SUPABASE_URL,secret=process.env.SUPABASE_SECRET_KEY;if(!url||!secret)throw new Error('Set SUPABASE_URL and SUPABASE_SECRET_KEY in this PowerShell window first.');
 const{readFile}=await import('node:fs/promises'),{createClient}=await import('@supabase/supabase-js');const rows=parseCsv(await readFile(filePath,'utf8'));if(!rows.length)throw new Error('The CSV has no accounts.');
 const admin=createClient(url,secret,{auth:{autoRefreshToken:false,persistSession:false,detectSessionInUrl:false}});const{data:list,error:listError}=await admin.auth.admin.listUsers({page:1,perPage:1000});if(listError)throw listError;const known=new Map(list.users.map(u=>[u.email.toLowerCase(),u]));let created=0,updated=0;
 const{data:stores,error:storeError}=await admin.from('stores').select('id,store_code');if(storeError)throw storeError;const storeMap=new Map(stores.map(s=>[s.store_code,s.id]));
 for(const row of rows){if(!row.login_id||!row.password||row.password.length<10)throw new Error('Every row needs a unique password of at least 10 characters. Missing/short password for '+(row.login_id||'unknown row'));if(!['store_manager','area_manager'].includes(row.role))throw new Error('Invalid role for '+row.login_id);const email=row.login_id.toLowerCase()+'@accounts.storenotes.app';let authUser=known.get(email);if(!authUser){const{data,error}=await admin.auth.admin.createUser({email,password:row.password,email_confirm:true,user_metadata:{login_id:row.login_id,full_name:row.full_name}});if(error)throw new Error(row.login_id+': '+error.message);authUser=data.user;known.set(email,authUser);created++}else updated++;
  const{error:profileError}=await admin.from('profiles').upsert({id:authUser.id,full_name:row.full_name,email,role:row.role,is_active:true},{onConflict:'id'});if(profileError)throw new Error(row.login_id+': '+profileError.message);const codes=row.store_ids.split('|').filter(Boolean),ids=codes.map(c=>storeMap.get(c));if(ids.some(x=>!x))throw new Error(row.login_id+': unknown store ID in '+row.store_ids);const{error:deleteError}=await admin.from('user_store_access').delete().eq('user_id',authUser.id);if(deleteError)throw deleteError;if(ids.length){const{error:accessError}=await admin.from('user_store_access').insert(ids.map(store_id=>({user_id:authUser.id,store_id})));if(accessError)throw new Error(row.login_id+': '+accessError.message)}console.log('Provisioned '+row.login_id+' ('+row.role+')');
 }
 console.log('Complete: '+created+' created, '+updated+' existing accounts synchronized.');
}

const MANIFEST={id:'/',name:'Store Notes',short_name:'Store Notes',description:'Retail store visit findings and action tracking',start_url:'/',scope:'/',display:'standalone',background_color:'#f4f7f5',theme_color:'#123c2d',icons:[{src:'/StoreNotes_icon.png',sizes:'1240x1240',type:'image/png',purpose:'any maskable'}]};
const SW=`const C='store-notes-v3';const A=['/','/manifest.webmanifest','/StoreNotes_icon.png'];self.addEventListener('install',e=>e.waitUntil(caches.open(C).then(c=>c.addAll(A))));self.addEventListener('activate',e=>e.waitUntil(caches.keys().then(k=>Promise.all(k.filter(x=>x!==C).map(x=>caches.delete(x))))));self.addEventListener('fetch',e=>{if(e.request.method!=='GET')return;e.respondWith(fetch(e.request).then(r=>{const x=r.clone();caches.open(C).then(c=>c.put(e.request,x));return r}).catch(()=>caches.match(e.request).then(r=>r||caches.match('/'))))});`;

function crc32(buf){let c=0xffffffff;for(const b of buf){c^=b;for(let k=0;k<8;k++)c=(c>>>1)^(0xedb88320&-(c&1))}return(c^0xffffffff)>>>0}
function chunk(type,data){const t=Buffer.from(type),out=Buffer.alloc(data.length+12);out.writeUInt32BE(data.length,0);t.copy(out,4);data.copy(out,8);out.writeUInt32BE(crc32(Buffer.concat([t,data])),8+data.length);return out}
function icon(size){const rows=[];for(let y=0;y<size;y++){const row=Buffer.alloc(1+size*4);for(let x=0;x<size;x++){const i=1+x*4,round=Math.hypot(x-size/2,y-size/2)<size*.43,gold=x>size*.23&&x<size*.77&&y>size*.23&&y<size*.77;row[i]=gold?218:round?18:244;row[i+1]=gold?174:round?60:247;row[i+2]=gold?49:round?45:245;row[i+3]=255}rows.push(row)}const ihdr=Buffer.alloc(13);ihdr.writeUInt32BE(size,0);ihdr.writeUInt32BE(size,4);ihdr[8]=8;ihdr[9]=6;return Buffer.concat([Buffer.from([137,80,78,71,13,10,26,10]),chunk('IHDR',ihdr),chunk('IDAT',deflateSync(Buffer.concat(rows))),chunk('IEND',Buffer.alloc(0))])}

function virtualPlugin(){return{name:'store-notes-virtual',resolveId(id){if(id==='/src.jsx'||id==='virtual:styles.css')return '\0'+id},load(id){if(id==='\0/src.jsx')return APP;if(id==='\0virtual:styles.css')return CSS},transform(code,id){if(id==='\0/src.jsx')return esbuildTransform(code,{loader:'jsx',jsx:'automatic',sourcemap:true,sourcefile:'src.jsx'})},configureServer(server){server.middlewares.use((req,res,next)=>{const files={'/':[HTML,'text/html'],'/manifest.webmanifest':[JSON.stringify(MANIFEST),'application/manifest+json'],'/sw.js':[SW,'text/javascript'],'/setup.sql':[FULL_SQL,'text/plain'],'/README.md':[README,'text/markdown'],'/StoreNotes_icon.png':[APP_ICON,'image/png'],'/icon-192.png':[icon(192),'image/png'],'/icon-512.png':[icon(512),'image/png']},pathname=(req.url||'/').split('?')[0];if(files[pathname]){res.setHeader('Content-Type',files[pathname][1]);res.end(files[pathname][0]);return}next()})},generateBundle(_opts,bundle){const entry=Object.values(bundle).find(x=>x.type==='chunk'&&x.isEntry),css=Object.values(bundle).find(x=>x.type==='asset'&&x.fileName.endsWith('.css'));if(entry){const tags=(css?'<link rel="stylesheet" href="/'+css.fileName+'">':'')+'<script type="module" src="/'+entry.fileName+'"></script>';this.emitFile({type:'asset',fileName:'index.html',source:HTML.replace('<script type="module" src="/src.jsx"></script>',tags)})}this.emitFile({type:'asset',fileName:'manifest.webmanifest',source:JSON.stringify(MANIFEST)});this.emitFile({type:'asset',fileName:'sw.js',source:SW});this.emitFile({type:'asset',fileName:'setup.sql',source:FULL_SQL});this.emitFile({type:'asset',fileName:'README.md',source:README});this.emitFile({type:'asset',fileName:'StoreNotes_icon.png',source:APP_ICON});this.emitFile({type:'asset',fileName:'icon-192.png',source:icon(192)});this.emitFile({type:'asset',fileName:'icon-512.png',source:icon(512)})}}}

const command=process.argv[2];
if(command==='sql')process.stdout.write(FULL_SQL);else if(command==='stores-sql')process.stdout.write(STORE_SQL);else if(command==='workflow-sql')process.stdout.write(WORKFLOW_SQL);else if(command==='notifications-sql')process.stdout.write(NOTIFICATION_SQL);else if(command==='users-template')process.stdout.write(USERS_TEMPLATE);else if(command==='provision-users')await provisionUsers(process.argv[3]||'users.csv');else if(command==='readme')process.stdout.write(README);else if(command==='build')await viteBuild({root:process.cwd(),plugins:[virtualPlugin()],build:{outDir:'dist',emptyOutDir:true,rollupOptions:{input:'/src.jsx'}}});else{const server=await createServer({root:process.cwd(),plugins:[virtualPlugin()],server:{host:'0.0.0.0'}});await server.listen();server.printUrls()}
